package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen0Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> config;
    private AnnotationIntrospector ai;
    private AnnotatedMember property;
    private JavaType baseType;

    // Test hierarchies
    public static class Base {}
    public static class Sub1 extends Base {}
    public static class Sub2 extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        config = mock(MapperConfig.class);
        ai = mock(AnnotationIntrospector.class);
        property = mock(AnnotatedMember.class);
        baseType = mock(JavaType.class);

        when(config.getAnnotationIntrospector()).thenReturn(ai);
        when(baseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectSubtypes_MinimalCase() {
        // Test case: No subtypes in annotation, no registered subtypes
        when(ai.findSubtypes(property)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        // Should at least contain the root type itself based on the logic
        boolean containsRoot = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Base.class)) {
                containsRoot = true;
                break;
            }
        }
        assertTrue("Result should contain the root type", containsRoot);
    }

    @Test
    public void testCollectSubtypes_WithAnnotationSubtypes() {
        // Test case: Subtypes found via AnnotationIntrospector
        NamedType annotatedSubtype = new NamedType(Sub1.class, "Sub1");
        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(annotatedSubtype));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        boolean foundSub1 = result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class));
        assertTrue("Should find subtype from annotation", foundSub1);
    }

    @Test
    public void testCollectSubtypes_WithRegisteredSubtypes() {
        // Test case: Subtypes found via registerSubtypes
        when(ai.findSubtypes(property)).thenReturn(null);
        resolver.registerSubtypes(new NamedType(Sub2.class, "Sub2"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        boolean foundSub2 = result.stream().anyMatch(nt -> nt.getType().equals(Sub2.class));
        assertTrue("Should find subtype from registration", foundSub2);
    }

    @Test
    public void testCollectSubtypes_WithAllSources() {
        // Test case: Combination of Hierarchy, Annotation, and Registration
        // 1. Hierarchy (handled by _collectAndResolveByTypeId calling root)
        // 2. Annotation
        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(new NamedType(Sub1.class, "Sub1")));
        // 3. Registration
        resolver.registerSubtypes(new NamedType(Sub2.class, "Sub2"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        boolean foundSub1 = result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class));
        boolean foundSub2 = result.stream().anyMatch(nt -> nt.getType().equals(Sub2.class));

        assertTrue("Should find subtype from annotation", foundSub1);
        assertTrue("Should find subtype from registration", foundSub2);
    }

    @Test
    public void testCollectSubtypes_IgnoreUnrelatedRegisteredSubtypes() {
        // Test case: Registered subtype is not a subclass of baseType
        when(ai.findSubtypes(property)).thenReturn(null);
        resolver.registerSubtypes(new NamedType(Unrelated.class, "Unrelated"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        boolean foundUnrelated = result.stream().anyMatch(nt -> nt.getType().equals(Unrelated.class));
        assertFalse("Should NOT include unrelated registered subtype", foundUnrelated);
    }

    @Test
    public void testCollectSubtypes_HandleEmptyAnnotationList() {
        // Test case: Annotation returns an empty collection instead of null
        when(ai.findSubtypes(property)).thenReturn(new HashSet<>());
        resolver.registerSubtypes(new NamedType(Sub1.class, "Sub1"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        boolean foundSub1 = result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class));
        assertTrue("Should still find registered subtype even if annotation is empty", foundSub1);
    }
}
